mapper.select:
SELECT COUNT(1) AS totalHits,
       COALESCE(SUM(CASE WHEN used_in_prompt = 1 THEN 1 ELSE 0 END), 0) AS usedInPromptCount
FROM t_knowledge_hit_record
WHERE tenant_id = #{tenantId}
  AND created_at >= #{from}
  AND created_at <= #{to}

SELECT DATE_FORMAT(created_at, '%Y-%m-%d') AS day,
       COUNT(1) AS hitCount,
       COALESCE(SUM(CASE WHEN used_in_prompt = 1 THEN 1 ELSE 0 END), 0) AS usedInPromptCount
FROM t_knowledge_hit_record
WHERE tenant_id = #{tenantId}
  AND created_at >= #{from}
  AND created_at <= #{to}
GROUP BY DATE_FORMAT(created_at, '%Y-%m-%d')
ORDER BY day ASC

SELECT COUNT(1) AS runCount,
       COALESCE(SUM(CASE WHEN status = 'COMPLETED' THEN 1 ELSE 0 END), 0) AS completedCount,
       COALESCE(SUM(CASE WHEN status = 'FAILED' THEN 1 ELSE 0 END), 0) AS failedCount,
       AVG(overall_score) AS avgOverallScore
FROM t_evaluation_run
WHERE tenant_id = #{tenantId}
  AND created_at >= #{from}
  AND created_at <= #{to}
